func (s *Session) Update(ctx context.Context) (err error) {
    tx, err := s.db.BeginTx(ctx, nil)
    if err != nil { return err }
    defer func() {                 // runs on return, on error and on panic
        if err != nil { _ = tx.Rollback() }
    }()
    if err = apply(tx); err != nil { return err }
    return tx.Commit()
}
